<?php require_once __DIR__.'/../includes/bootstrap.php';if(!is_admin()){header('Location: ../login.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]);}$orders=$pdo->query("SELECT o.*,u.full_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll();$pageTitle='مدیریت سفارش‌ها';include __DIR__.'/../includes/header.php';?><main class="page-content container"><h1 class="page-title">مدیریت سفارش‌ها</h1><div class="table-wrap"><table class="data-table"><tr><th>کد</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>به‌روزرسانی</th></tr><?php foreach($orders as $o):?><tr><td><?=$o['id']?></td><td><?=e($o['full_name'])?></td><td><?=toman($o['total_amount'])?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><option>pending</option><option>processing</option><option>shipped</option><option>completed</option><option>cancelled</option></select><button>ثبت</button></form></td></tr><?php endforeach;?></table></div></main><?php include __DIR__.'/../includes/footer.php';?>
